def tokenize(text, lead_atom=None):
    """Split on spaces, but keep links and code spans whole."""
    toks, pos = [], 0
    if lead_atom:
        toks.append(lead_atom)
        pos = len(lead_atom)
        while pos < len(text) and text[pos] == ' ':
            pos += 1
    buf = ''
    while pos < len(text):
        m = ATOM.match(text, pos)
        if m:
            buf += m.group(0)
            pos = m.end()
            continue
        ch = text[pos]
        pos += 1
        if ch == ' ':
            if buf:
                toks.append(buf); buf = ''
        else:
            buf += ch
    if buf:
        toks.append(buf)
    return toks

def wrap(toks, first, cont):
    lines, cur = [], None
    for t in toks:
        if cur is None:
            cur = first + t
        elif blen(cur + ' ' + t) <= LIMIT:
            cur += ' ' + t
        else:
            lines.append(cur)
            cur = cont + t
    return lines + ([cur] if cur is not None else [])

